package com.bank.jsonidx.service;
import com.bank.jsonidx.model.Customer;
import java.util.*;
import java.util.logging.*;

public class IndexedKycStore {
    private static final Logger log = Logger.getLogger(IndexedKycStore.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    // GIN analogue: "key=value" token → ids containing it
    private final Map<String, Set<String>> ginIndex = new HashMap<>();
    // b-tree expression analogue: status value → ids
    private final Map<String, Set<String>> statusIndex = new TreeMap<>();

    public IndexedKycStore(List<Customer> customers) {
        for (Customer c : customers) {
            c.getKyc().forEach((k, v) ->
                ginIndex.computeIfAbsent(k + "=" + v, x -> new LinkedHashSet<>()).add(c.getId()));
            statusIndex.computeIfAbsent(c.getKyc().get("status"), x -> new LinkedHashSet<>()).add(c.getId());
        }
    }
    // kyc @> {"status":"active"}  → GIN containment lookup
    public Set<String> byContainment(String key, String value) {
        Set<String> ids = ginIndex.getOrDefault(key + "=" + value, Set.of());
        log.info(() -> "GIN @> {" + key + ":" + value + "} -> " + ids);
        return ids;
    }
    // kyc->>'status' = 'active'  → b-tree expression lookup
    public Set<String> byStatus(String status) {
        Set<String> ids = statusIndex.getOrDefault(status, Set.of());
        log.info(() -> "btree status=" + status + " -> " + ids);
        return ids;
    }
}
