package com.bank.jsonidx;
import com.bank.jsonidx.model.Customer;
import com.bank.jsonidx.service.IndexedKycStore;
import java.util.*;
import java.util.logging.*;

public class IndexDemo {
    public static void main(String[] args) {
        IndexedKycStore store = new IndexedKycStore(List.of(
            new Customer("SAV2001","Rajesh Kumar", Map.of("status","active","city","Delhi")),
            new Customer("CUR3001","Priya Sharma", Map.of("status","pending","city","Delhi"))));
        System.out.println("containment -> " + store.byContainment("status","active"));
        System.out.println("btree       -> " + store.byStatus("active"));
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
